/// The closed neon palette. Mapped onto the theme in `ui.rs`, never to raw
/// colors, so the city follows whatever palette the person picked.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Neon {
    Cyan,
    Magenta,
    Red,
    Amber,
    Green,
    White,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Zone {
    pub x0: u16,
    pub y0: u16,
    pub x1: u16,
    pub y1: u16,
}

impl Zone {
    pub fn contains(&self, x: u16, y: u16) -> bool {
        x >= self.x0 && x <= self.x1 && y >= self.y0 && y <= self.y1
    }

    /// Chebyshev distance from a point to this rectangle (0 when inside).
    pub fn distance(&self, x: u16, y: u16) -> u16 {
        let dx = self.x0.saturating_sub(x).max(x.saturating_sub(self.x1));
        let dy = self.y0.saturating_sub(y).max(y.saturating_sub(self.y1));
        dx.max(dy)
    }
}

/// Everything on the street you can walk up to, in popover priority order.
/// The shops are the wallet (GAME.md); the rest is the street.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Landmark {
    Armorer,
    Tailor,
    Lockers,
    Bands,
    Bar,
    Screen,
    Repairs,
    Board,
    Bits,
    Noodles,
    Umbrellas,
    Blades,
    Reader,
    Stairs,
    Wire,
}

impl Landmark {
    /// Every landmark, in popover priority order.
    pub const ALL: [Landmark; 15] = [
        Landmark::Armorer,
        Landmark::Tailor,
        Landmark::Lockers,
        Landmark::Bands,
        Landmark::Bar,
        Landmark::Screen,
        Landmark::Repairs,
        Landmark::Board,
        Landmark::Bits,
        Landmark::Noodles,
        Landmark::Umbrellas,
        Landmark::Blades,
        Landmark::Reader,
        Landmark::Stairs,
        Landmark::Wire,
    ];

    /// The cells that put the player within reach: the sidewalk in front
    /// of a door, the ring around a cart.
    #[rustfmt::skip]
    pub fn reach(self) -> Zone {
        match self {
            Landmark::Armorer => Zone { x0: 31, y0: 20, x1: 36, y1: 21 },
            Landmark::Tailor => Zone { x0: 64, y0: 20, x1: 69, y1: 21 },
            Landmark::Lockers => Zone { x0: 95, y0: 20, x1: 100, y1: 21 },
            Landmark::Bands => Zone { x0: 124, y0: 20, x1: 129, y1: 21 },
            Landmark::Bar => Zone { x0: 154, y0: 20, x1: 159, y1: 21 },
            Landmark::Screen => Zone { x0: 176, y0: 20, x1: 201, y1: 21 },
            Landmark::Repairs => Zone { x0: 214, y0: 20, x1: 219, y1: 21 },
            Landmark::Board => Zone { x0: 98, y0: 21, x1: 110, y1: 27 },
            Landmark::Bits => Zone { x0: 170, y0: 21, x1: 177, y1: 25 },
            Landmark::Noodles => Zone { x0: 40, y0: 24, x1: 52, y1: 28 },
            Landmark::Umbrellas => Zone { x0: 66, y0: 31, x1: 82, y1: 35 },
            Landmark::Blades => Zone { x0: 132, y0: 32, x1: 145, y1: 35 },
            Landmark::Reader => Zone { x0: 192, y0: 24, x1: 203, y1: 28 },
            Landmark::Stairs => Zone { x0: 2, y0: 20, x1: 15, y1: 21 },
            Landmark::Wire => Zone { x0: 110, y0: 37, x1: 121, y1: 38 },
        }
    }

    /// How close the player has to stand.
    fn reach_distance(self) -> u16 {
        match self {
            Landmark::Noodles
            | Landmark::Umbrellas
            | Landmark::Blades
            | Landmark::Reader
            | Landmark::Board
            | Landmark::Bits => 1,
            Landmark::Armorer
            | Landmark::Tailor
            | Landmark::Lockers
            | Landmark::Bands
            | Landmark::Bar
            | Landmark::Screen
            | Landmark::Repairs
            | Landmark::Stairs
            | Landmark::Wire => 0,
        }
    }
}

/// The landmark the player is close enough to, if any.
pub fn nearest_landmark(x: u16, y: u16) -> Option<Landmark> {
    Landmark::ALL
        .into_iter()
        .find(|landmark| landmark.reach().distance(x, y) <= landmark.reach_distance())
}

/// The street as a padded char grid, decoded once per process.
pub fn grid() -> &'static [Vec<char>] {
    static GRID: std::sync::OnceLock<Vec<Vec<char>>> = std::sync::OnceLock::new();
    GRID.get_or_init(|| {
        MAP.iter()
            .map(|row| {
                let mut cells: Vec<char> = row.chars().collect();
                cells.resize(MAP_W as usize, ' ');
                cells
            })
            .collect()
    })
}

/// The map char at `(x, y)`; rows shorter than `MAP_W` read as open street.
pub fn char_at(x: u16, y: u16) -> char {
    if x >= MAP_W || y >= MAP_H {
        return ' ';
    }
    grid()[y as usize][x as usize]
}

/// Whether a runner can stand on `(x, y)`: the solid bitmap says no for
/// walls, facades, carts, the railing and the drop.
pub fn walkable(x: u16, y: u16) -> bool {
    if x == 0 || y == 0 || x >= MAP_W - 1 || y >= MAP_H - 1 {
        return false;
    }
    SOLID[y as usize].as_bytes()[x as usize] == b'.'
}

